1	import { SUBPAGE_STARFIELD } from "../config/component.config.js";
2	import { FrameScheduler } from "../utils/FrameScheduler.js";
3	import { ResponsiveRuntime } from "./ResponsiveRuntime.js";
4	import type { SubpageStarfieldStar } from "../types/component.types.js";
5	
6	export class SubpageStarfieldRuntime {
7	  private _canvas: HTMLCanvasElement | null = null;
8	  private _context: CanvasRenderingContext2D | null = null;
9	  private _stars: SubpageStarfieldStar[] = [];
10	  private _width = 0;
11	  private _height = 0;
12	  private _centerX = 0;
13	  private _centerY = 0;
14	  private _rafId: number | null = null;
15	  private _pageshowListenerAttached = false;
16	  private _resizeListener: (() => void) | null = null;
17	  private _scrollListener: (() => void) | null = null;
18	  private _scrollBoost = 0;
19	  private _targetScrollBoost = 0;
20	  private _lastScrollY = 0;
21	  private _lastFrameTime = 0;
22	
23	  init(root?: ParentNode | null): void {
24	    this.dispose();
25	    if (!this._isEligible()) return;
26	    const scope = root ?? document;
27	    const canvas = scope.querySelector<HTMLCanvasElement>(
28	      SUBPAGE_STARFIELD.canvasSelector,
29	    );
30	    if (!canvas) return;
31	    const context = canvas.getContext("2d");
32	    if (!context) return;
33	    this._canvas = canvas;
34	    this._context = context;
35	    this._lastScrollY = window.scrollY ?? window.pageYOffset ?? 0;
36	    this._bindEvents();
37	    this._resize();
38	    this._seedStars();
39	    this._lastFrameTime = performance.now();
40	    this._startLoop();
41	    if (!this._pageshowListenerAttached) {
42	      window.addEventListener("pageshow", this._pageshowHandler);
43	      this._pageshowListenerAttached = true;
44	    }
45	  }
46	
47	  dispose(): void {
48	    if (this._rafId !== null) {
49	      FrameScheduler.cancel(this._rafId);
50	      this._rafId = null;
51	    }
52	    if (this._pageshowListenerAttached) {
53	      window.removeEventListener("pageshow", this._pageshowHandler);
54	      this._pageshowListenerAttached = false;
55	    }
56	    if (this._resizeListener) {
57	      window.removeEventListener("resize", this._resizeListener);
58	      this._resizeListener = null;
59	    }
60	    if (this._scrollListener) {
61	      window.removeEventListener("scroll", this._scrollListener);
62	      this._scrollListener = null;
63	    }
64	    this._canvas = null;
65	    this._context = null;
66	    this._stars = [];
67	    this._width = 0;
68	    this._height = 0;
69	    this._centerX = 0;
70	    this._centerY = 0;
71	    this._scrollBoost = 0;
72	    this._targetScrollBoost = 0;
73	    this._lastScrollY = 0;
74	    this._lastFrameTime = 0;
75	  }
76	
77	  private _isEligible(): boolean {
78	    const pathname = window.location.pathname || "/";
79	    return SUBPAGE_STARFIELD.pagePrefixes.some((prefix) =>
80	      pathname.startsWith(prefix),
81	    );
82	  }
83	
84	  private readonly _pageshowHandler = (e: PageTransitionEvent): void => {
85	    if (!e.persisted) return;
86	    if (!this._canvas) return;
87	    // bfcache 복원: RAF 체인 끊김 → 취소 후 재시작
88	    if (this._rafId !== null) {
89	      FrameScheduler.cancel(this._rafId);
90	      this._rafId = null;
91	    }
92	    this._lastFrameTime = performance.now();
93	    this._startLoop();
94	  };
95	
96	  private _bindEvents(): void {
97	    this._resizeListener = () => this._resize();
98	    this._scrollListener = () => this._syncScrollBoost();
99	    window.addEventListener("resize", this._resizeListener);
100	    window.addEventListener("scroll", this._scrollListener, { passive: true });
101	  }
102	
103	  private _resize(): void {
104	    if (!this._canvas || !this._context) return;
105	    const bounds = this._canvas.getBoundingClientRect();
106	    const width = Math.max(1, Math.round(bounds.width));
107	    const height = Math.max(1, Math.round(bounds.height));
108	    const dpr = Math.min(
109	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
110	      SUBPAGE_STARFIELD.pixelRatioMax,
111	    );
112	    this._width = width;
113	    this._height = height;
114	    this._centerX = width * 0.5;
115	    this._centerY = height * 0.5;
116	    this._canvas.width = Math.round(width * dpr);
117	    this._canvas.height = Math.round(height * dpr);
118	    this._context.setTransform(dpr, 0, 0, dpr, 0, 0);
119	  }
120	
121	  private _syncScrollBoost(): void {
122	    const nextY = window.scrollY ?? window.pageYOffset ?? 0;
123	    const delta = Math.abs(nextY - this._lastScrollY);
124	    this._lastScrollY = nextY;
125	    const viewportHeight = Math.max(window.innerHeight || 0, 1);
126	    const normalizedBoost = Math.min(
127	      (delta / viewportHeight) * SUBPAGE_STARFIELD.scrollBoostFactor,
128	      SUBPAGE_STARFIELD.scrollBoostMax,
129	    );
130	    this._targetScrollBoost = Math.max(this._targetScrollBoost, normalizedBoost);
131	  }
132	
133	  private _seedStars(): void {
134	    this._stars = Array.from(
135	      { length: SUBPAGE_STARFIELD.starCount },
136	      () => this._createStar(),
137	    );
138	  }
139	
140	  private _startLoop(): void {
141	    const render = (): void => {
142	      this._render();
143	      this._rafId = FrameScheduler.request(render);
144	    };
145	    render();
146	  }
147	
148	  private _render(): void {
149	    if (!this._context || this._width <= 0 || this._height <= 0) {
150	      return;
151	    }
152	    const now = performance.now();
153	    const delta = Math.min((now - this._lastFrameTime) / 1000, 1 / 24);
154	    this._lastFrameTime = now;
155	    this._targetScrollBoost = Math.max(
156	      0,
157	      this._targetScrollBoost - delta * SUBPAGE_STARFIELD.scrollBoostDecayPerSecond,
158	    );
159	    const lerpFactor = Math.min(
160	      1,
161	      delta * SUBPAGE_STARFIELD.scrollBoostLerpPerSecond,
162	    );
163	    this._scrollBoost +=
164	      (this._targetScrollBoost - this._scrollBoost) * lerpFactor;
165	
166	    const context = this._context;
167	    const speed = SUBPAGE_STARFIELD.speed + this._scrollBoost;
168	    context.fillStyle = `rgba(0, 0, 0, ${SUBPAGE_STARFIELD.clearAlpha})`;
169	    context.fillRect(0, 0, this._width, this._height);
170	
171	    for (const star of this._stars) {
172	      star.z -= speed;
173	      if (star.z <= 0) {
174	        this._resetStar(star);
175	      }
176	
177	      const screenX = (star.x / star.z) * this._width + this._centerX;
178	      const screenY = (star.y / star.z) * this._height + this._centerY;
179	      const previousX = (star.x / star.previousZ) * this._width + this._centerX;
180	      const previousY = (star.y / star.previousZ) * this._height + this._centerY;
181	      const brightness = Math.max(
182	        0,
183	        Math.min(
184	          255,
185	          Math.floor((1 - star.z / (this._width * SUBPAGE_STARFIELD.depthRangeFactor)) * 255),
186	        ),
187	      );
188	      const radius = Math.max(
189	        SUBPAGE_STARFIELD.radiusMin,
190	        (1 - star.z / (this._width * SUBPAGE_STARFIELD.depthRangeFactor)) *
191	          SUBPAGE_STARFIELD.radiusMax,
192	      );
193	
194	      context.beginPath();
195	      context.moveTo(previousX, previousY);
196	      context.lineTo(screenX, screenY);
197	      context.strokeStyle = `rgba(${brightness}, ${brightness}, ${brightness}, 1)`;
198	      context.lineWidth = radius;
199	      context.stroke();
200	
201	      star.previousZ = star.z;
202	    }
203	  }
204	
205	  private _createStar(): SubpageStarfieldStar {
206	    return this._resetStar({
207	      x: 0,
208	      y: 0,
209	      z: 0,
210	      previousZ: 0,
211	    });
212	  }
213	
214	  private _resetStar(star: SubpageStarfieldStar): SubpageStarfieldStar {
215	    star.x = (Math.random() - 0.5) * this._width;
216	    star.y = (Math.random() - 0.5) * this._height;
217	    star.z = Math.random() * (this._width * SUBPAGE_STARFIELD.depthRangeFactor);
218	    star.previousZ = star.z;
219	    return star;
220	  }
221	}
