336	    const dy = pointer.y - this._dragPrevious.y;
337	    this._targetX += (-dx * (halfView.hW * 2)) / viewport.width;
338	    this._targetY += (dy * (halfView.hH * 2)) / viewport.height;
339	    this._velocityX = ((-dx * (halfView.hW * 2)) / viewport.width) * 0.7 * velMultiplier;
