1000	  private _readVisiblePositionsCenter(
1001	    positions: ReadonlyArray<WorksScatterPosition>,
1002	  ): WorksScatterPosition {
1003	    if (positions.length === 0) {
1004	      return { x: 0, y: 0 };
1005	    }
1006	    let minX = positions[0]?.x ?? 0;
1007	    let maxX = minX;
1008	    let minY = positions[0]?.y ?? 0;
1009	    let maxY = minY;
1010	    for (let index = 1; index < positions.length; index += 1) {
1011	      const position = positions[index];
1012	      if (!position) continue;
1013	      minX = Math.min(minX, position.x);
1014	      maxX = Math.max(maxX, position.x);
1015	      minY = Math.min(minY, position.y);
1016	      maxY = Math.max(maxY, position.y);
1017	    }
1018	    return {
1019	      x: (minX + maxX) * 0.5,
1020	      y: (minY + maxY) * 0.5,
1021	    };
