145	
146	  private _setupGlobalBloom(
147	    bloomCfg: Required<Omit<BloomOptions, "selective">> & {
148	      selective: boolean;
149	    },
150	    resolution: THREE.Vector2,
151	    vignetteCfg: Required<VignetteOptions> | null,
152	  ): void {
153	    this._composer = new EffectComposer(this._renderer);
154	    this._composer.addPass(new RenderPass(this._scene, this._camera));
155	    this._bloomPass = new UnrealBloomPass(
156	      resolution,
157	      bloomCfg.strength,
158	      bloomCfg.radius,
159	      bloomCfg.threshold,
160	    );
161	    this._composer.addPass(this._bloomPass);
