179	  render(bloomRoots: Set<THREE.Object3D>, deltaTime?: number): void {
180	    if (!this._bloomPass) {
181	      if (this._composer) {
182	        this._composer.render(deltaTime);
183	        return;
184	      }
185	      this._renderer.render(this._scene, this._camera);
186	      return;
187	    }
188	
189	    if (this._selective) {
190	      const hasRoots = this._hasRenderableBloomRoots(bloomRoots);
