197	  private _renderSelective(
198	    bloomRoots: Set<THREE.Object3D>,
199	    hasRoots: boolean,
200	    deltaTime?: number,
201	  ): void {
202	    if (
203	      !this._selective ||
204	      !this._bloomComposer ||
205	      !this._finalComposer ||
206	      !this._darkMaterial
207	    ) {
208	      this._composer?.render(deltaTime);
209	      return;
