248	      this._cachedBloomSignature = signature;
249	      this._rebuildNonBloomMeshCache(bloomRoots);
250	    }
251	
252	    for (const mesh of this._cachedNonBloomMeshes) {
253	      this._materialCache.set(mesh, mesh.material);
