274	    }
275	    return false;
276	  }
277	
278	  private _normalizeBloomOptions(
279	    bloomOpt: PostProcessorOptions["bloom"],
280	  ): Required<Omit<BloomOptions, "selective">> & { selective: boolean } {
281	    if (typeof bloomOpt !== "object" || bloomOpt == null) {
282	      return { ...DEFAULT_BLOOM };
283	    }
284	    const strength = this._clampFinite(
285	      bloomOpt.strength,
286	      DEFAULT_BLOOM.strength,
287	      0,
288	      5,
289	    );
290	    const radius = this._clampFinite(
291	      bloomOpt.radius,
292	      DEFAULT_BLOOM.radius,
293	      0,
294	      2,
295	    );
296	    const threshold = this._clampFinite(
297	      bloomOpt.threshold,
298	      DEFAULT_BLOOM.threshold,
299	      0,
300	      2,
301	    );
302	    const compositeStrength = this._clampFinite(
303	      bloomOpt.compositeStrength,
304	      DEFAULT_BLOOM.compositeStrength,
305	      0,
306	      1,
307	    );
308	    const selective =
309	      typeof bloomOpt.selective === "boolean"
310	        ? bloomOpt.selective
311	        : DEFAULT_BLOOM.selective;
312	    return { strength, radius, threshold, compositeStrength, selective };
313	  }
314	
315	  private _normalizeVignetteOptions(
316	    vignetteOpt: PostProcessorOptions["vignette"],
317	  ): Required<VignetteOptions> | null {
318	    if (vignetteOpt === false || vignetteOpt == null) return null;
319	    if (vignetteOpt === true) return { ...DEFAULT_VIGNETTE };
320	    return {
321	      offset: this._clampFinite(
322	        vignetteOpt.offset,
323	        DEFAULT_VIGNETTE.offset,
324	        0,
325	        4,
326	      ),
327	      darkness: this._clampFinite(
328	        vignetteOpt.darkness,
329	        DEFAULT_VIGNETTE.darkness,
330	        0,
331	        4,
332	      ),
333	    };
334	  }
335	
336	  private _createVignettePass(
337	    vignetteCfg: Required<VignetteOptions>,
338	  ): ShaderPass {
339	    const pass = new ShaderPass(VignetteShader);
340	    pass.uniforms.offset.value = vignetteCfg.offset;
341	    pass.uniforms.darkness.value = vignetteCfg.darkness;
342	    return pass;
343	  }
344	
345	  private _clampFinite(
346	    value: number | undefined,
347	    fallback: number,
348	    min: number,
349	    max: number,
350	  ): number {
351	    if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
352	    return Math.max(min, Math.min(max, value));
353	  }
354	
355	  private _restoreMaterials(): void {
356	    for (const [mesh, material] of this._materialCache) {
357	      (mesh as THREE.Mesh).material = material;
358	    }
359	    this._materialCache.clear();
360	  }
361	
362	  private _createBloomSignature(bloomRoots: Set<THREE.Object3D>): string {
363	    return Array.from(bloomRoots)
364	      .filter((root) => !!root.parent)
365	      .map((root) => root.uuid)
366	      .sort()
367	      .join("|");
368	  }
369	
370	  private _rebuildNonBloomMeshCache(bloomRoots: Set<THREE.Object3D>): void {
371	    this._bloomDescendants.clear();
372	    for (const root of bloomRoots) {
373	      root.traverse((child) => this._bloomDescendants.add(child));
374	    }
375	    this._cachedSceneMeshes = this._collectSceneMeshes();
376	    this._cachedNonBloomMeshes = this._cachedSceneMeshes.filter(
377	      (mesh) => !this._bloomDescendants.has(mesh),
378	    );
379	  }
380	
381	  private _collectSceneMeshes(): THREE.Mesh[] {
382	    const meshes: THREE.Mesh[] = [];
383	    this._scene.traverse((obj) => {
384	      const mesh = obj as THREE.Mesh;
385	      if (!mesh.isMesh) return;
386	      meshes.push(mesh);
387	    });
388	    return meshes;
389	  }
