401	      this._bloomComposer?.setPixelRatio(dpr);
402	      this._finalComposer?.setSize(width, height);
403	      this._finalComposer?.setPixelRatio(dpr);
404	    } else {
405	      this._composer?.setSize(width, height);
406	      this._composer?.setPixelRatio(dpr);
407	    }
