420	  }
421	
422	  getBloomOptions(): Required<Omit<BloomOptions, "selective">> | null {
423	    if (!this._bloomPass) return null;
424	    return {
425	      strength: this._bloomPass.strength,
426	      radius: this._bloomPass.radius,
427	      threshold: this._bloomPass.threshold,
428	      compositeStrength: this._readBloomCompositeStrength(),
429	    };
430	  }
431	
432	  setBloomOptions(options: BloomOptions): void {
433	    if (!this._bloomPass) return;
434	    const normalized = this._normalizeBloomOptions(options);
435	    this._bloomPass.strength = normalized.strength;
436	    this._bloomPass.radius = normalized.radius;
437	    this._bloomPass.threshold = normalized.threshold;
438	    const blendUniform = this._blendPass?.uniforms?.bloomMix;
439	    if (blendUniform) {
440	      blendUniform.value = normalized.compositeStrength;
