448	      offset: uniforms.offset.value,
449	      darkness: uniforms.darkness.value,
450	    };
451	  }
452	
453	  setVignetteOptions(options: VignetteOptions): void {
454	    const uniforms = this._vignettePass?.uniforms;
455	    if (!uniforms) return;
456	    const normalized = this._normalizeVignetteOptions(options);
457	    if (!normalized) return;
458	    uniforms.offset.value = normalized.offset;
459	    uniforms.darkness.value = normalized.darkness;
460	  }
461	
462	  dispose(): void {
463	    this._composer?.dispose();
464	    this._composer = null;
465	    this._bloomComposer?.dispose();
466	    this._bloomComposer = null;
467	    this._finalComposer?.dispose();
468	    this._finalComposer = null;
469	    this._bloomPass?.dispose();
470	    this._bloomPass = null;
471	    this._blendPass = null;
472	    this._vignettePass = null;
473	    this._darkMaterial?.dispose();
474	    this._darkMaterial = null;
475	    this._materialCache.clear();
476	    this._bloomDescendants.clear();
477	    this._cachedBloomSignature = "";
478	    this._cachedNonBloomMeshes = [];
479	    this._cachedSceneMeshes = [];
480	    this._didWarnSelectiveFallback = false;
481	  }
482	
483	  private _readBloomCompositeStrength(): number {
484	    const uniform = this._blendPass?.uniforms?.bloomMix;
485	    if (!uniform || typeof uniform.value !== "number") {
486	      return DEFAULT_BLOOM.compositeStrength;
487	    }
488	    return uniform.value;
489	  }
